/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `calculate_hours_worked_insert` BEFORE INSERT ON `clock_hour` FOR EACH ROW BEGIN
    DECLARE total_minutes_raw INT;
    DECLARE lunch_break_start_time TIME DEFAULT '12:00:00';
    DECLARE lunch_break_end_time TIME DEFAULT '13:00:00';
    DECLARE deducted_lunch_minutes INT DEFAULT 0;

    -- Only calculate if both clock_in and clock_out are provided
    IF NEW.clock_in_time IS NOT NULL AND NEW.clock_out_time IS NOT NULL THEN

        -- Calculate total raw minutes worked (difference without break)
        SET total_minutes_raw = TIMESTAMPDIFF(MINUTE, NEW.clock_in_time, NEW.clock_out_time);

        -- Ensure clock_out_time is after clock_in_time for valid duration
        IF NEW.clock_in_time < NEW.clock_out_time THEN

            -- Calculate the specific date of the clock-in/out
            SET @current_date = DATE(NEW.clock_in_time);

            -- Define the full DATETIME for the lunch break boundaries on that day
            SET @lunch_start_datetime = CONCAT(@current_date, ' ', lunch_break_start_time);
            SET @lunch_end_datetime = CONCAT(@current_date, ' ', lunch_break_end_time);

            -- Determine the intersection of the work period and the lunch break period
            SET @overlap_start = GREATEST(NEW.clock_in_time, @lunch_start_datetime);
            SET @overlap_end = LEAST(NEW.clock_out_time, @lunch_end_datetime);

            -- If there is an overlap, calculate its duration
            IF @overlap_start < @overlap_end THEN
                SET deducted_lunch_minutes = TIMESTAMPDIFF(MINUTE, @overlap_start, @overlap_end);
            END IF;

            -- Subtract the calculated overlap from total_minutes_raw
            SET NEW.hours_worked = (total_minutes_raw - deducted_lunch_minutes) / 60.0;

        ELSE
            -- Clock_out_time is not after clock_in_time (e.g., clocked out before clocked in, or on next day without explicit handling)
            SET NEW.hours_worked = 0;
        END IF;

        -- Ensure hours_worked is not negative (e.g., if a tiny work duration was entirely within a break)
        IF NEW.hours_worked < 0 THEN
            SET NEW.hours_worked = 0;
        END IF;
    ELSE
        SET NEW.hours_worked = 0;
    END IF;
END */;;
DELIMITER ;
