CREATE TABLE `employee` (
  `employee_id` int NOT NULL AUTO_INCREMENT,
  `first_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `gender` enum('MALE','FEMALE') DEFAULT NULL,
  `birthday` date NOT NULL,
  `phone_number` varchar(15) NOT NULL,
  `sss_number` varchar(15) NOT NULL,
  `philhealth_number` varchar(15) NOT NULL,
  `tin_number` varchar(15) NOT NULL,
  `pagibig_number` varchar(15) NOT NULL,
  `employment_status` enum('REGULAR','PROBATIONARY') NOT NULL,
  `department` enum('HUMAN_RESOURCES','INFORMATION_TECHNOLOGY','FINANCE','SALES_AND_MARKETING','SUPPLY_CHAIN_AND_LOGISTICS','CUSTOMER_SERVICE','OPERATIONS') DEFAULT NULL,
  `supervisor_id` int DEFAULT NULL,
  `position_salary_history_id` int NOT NULL,
  PRIMARY KEY (`employee_id`),
  UNIQUE KEY `sss_number_UNIQUE` (`sss_number`),
  UNIQUE KEY `tin_number_UNIQUE` (`tin_number`),
  UNIQUE KEY `philhealth_number_UNIQUE` (`philhealth_number`),
  UNIQUE KEY `pagibig_number_UNIQUE` (`pagibig_number`),
  UNIQUE KEY `uq_employee_unique` (`first_name`,`last_name`,`birthday`),
  KEY `fk_employee_positionHistId_positionSalaryHistory_positionHistId` (`position_salary_history_id`),
  KEY `fk_employee_supervisorId` (`supervisor_id`) /*!80000 INVISIBLE */,
  CONSTRAINT `fk_employee_positionHistId_positionSalaryHistory_positionHistId` FOREIGN KEY (`position_salary_history_id`) REFERENCES `position_salary_history` (`position_salary_history_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_employee_supervisorId` FOREIGN KEY (`supervisor_id`) REFERENCES `employee` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_pagibig_format` CHECK (regexp_like(`pagibig_number`,_utf8mb4'^[0-9]{12}$')),
  CONSTRAINT `chk_philhealth_format` CHECK (regexp_like(`philhealth_number`,_utf8mb4'^[0-9]{12}$')),
  CONSTRAINT `chk_phone_format` CHECK (regexp_like(`phone_number`,_utf8mb4'^[0-9]{3}-[0-9]{3}-[0-9]{3}$')),
  CONSTRAINT `chk_sss_format` CHECK (regexp_like(`sss_number`,_utf8mb4'^[0-9]{2}-[0-9]{7}-[0-9]{1}$')),
  CONSTRAINT `chk_tin_format` CHECK (regexp_like(`tin_number`,_utf8mb4'^[0-9]{3}-[0-9]{3}-[0-9]{3}-[0-9]{3}$'))
) ENGINE=InnoDB AUTO_INCREMENT=10037 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
