/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_create_leave_entitlements_AFTER_EMPLOYEE_INSERT` AFTER INSERT ON `employee` FOR EACH ROW BEGIN
     -- Create leave entitlements for each active leave type per gender
    IF NEW.gender = 'Female' THEN
		INSERT INTO leave_entitlement (employee_id, leave_type_id, entitlement_days, year)
        SELECT NEW.employee_id, lt.leave_type_id, lt.max_days_allowed, YEAR(CURDATE())
        FROM leave_type lt
        WHERE lt.is_active = 1 AND lt.name NOT IN ('Paternity Leave');
        
    ELSEIF NEW.gender = 'Male' THEN
        INSERT INTO leave_entitlement (employee_id, leave_type_id, entitlement_days, year)
        SELECT NEW.employee_id, lt.leave_type_id, lt.max_days_allowed, YEAR(CURDATE())
        FROM leave_type lt
        WHERE lt.is_active = 1 AND lt.name NOT IN ('Maternity Leave', 'Special Leave For Women', 'VAWC Leave');
    END IF;
END */;;
DELIMITER ;
