INSERT INTO `leave_type` VALUES (1,'Service Incentive Leave (SIL)','Employees with at least twelve months of service are entitled to 5 days of paid leave credits, allowing them to take time off for any reason. Employers must compensate employees for any unused leave credits in cash.',5,1),(2,'Maternity Leave','Maternity leave is initially granted for 105 days with full pay, applicable to live childbirth, miscarriage, or emergency termination of pregnancy. Solo parents are entitled to an additional 15 days of fully paid leave. Employees may extend the leave for an additional 30 days, but this extended period will be unpaid.',135,1),(3,'Paternity Leave','Fathers are eligible for a fully paid paternity leave of up to 7 days. Additionally, the employee’s wife (the female employee who gave birth) can transfer 7 days of maternity leave to the father of the child. This way, the father is entitled to 14 days of paternity leave.',7,1),(4,'Special Leave For Women','Female employees with at least six months of continuous service in the last year are eligible for 2 months of fully paid leave following gynecological surgery.',62,1),(5,'VAWC Leave','Female employees who are victims or victim-survivors of violence or abuse as defined under Republic Act No. 9262, or the Anti-Violence Against Women and Their Children Act, are entitled to a leave of absence with full pay for a period of up to ten (10) days. To be entitled to the 10-day VAWC leave, the victim-employee must present to her employer a certification that an action for VAAWC has been filed or is pending.',10,1);
/*!40000 ALTER TABLE `leave_type` ENABLE KEYS */;
UNLOCK TABLES;

