/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `pagibig_rates_before_insert` BEFORE INSERT ON `pagibig_rates_history` FOR EACH ROW BEGIN
    -- Set default start date if not provided
    IF NEW.effective_start_date IS NULL THEN
        SET NEW.effective_start_date = CURDATE();
    END IF;

    -- Validate that min_amount <= max_amount (if max is not NULL)
    IF NEW.max_amount IS NOT NULL AND NEW.min_amount > NEW.max_amount THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'min_amount cannot be greater than max_amount';
    END IF;

    -- Validate that contribution is positive
    IF NEW.total_contribution <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'total_contribution must be positive';
    END IF;

   	-- ❗Note: Can't update same table here; handle end-dating in app logic or stored procedure
END */;;
