/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ApproveLeave`(
    IN v_leave_record_id INT,
    IN v_approved_by INT,
    IN v_remarks TEXT
)
BEGIN
    -- Variables
    DECLARE v_employee_id INT;
    DECLARE v_leave_type_id INT;
    DECLARE v_days_used INT;
    DECLARE v_applied_start_date DATE;
    DECLARE v_current_status ENUM('PENDING','APPROVED','REJECTED');
    DECLARE v_leave_year INT;
    DECLARE v_entitlement_days INT DEFAULT 0;
    DECLARE v_already_used_days INT DEFAULT 0;
    DECLARE v_remaining_days INT DEFAULT 0;
    DECLARE v_affected_rows INT DEFAULT 0;
	DECLARE v_error_message TEXT; -- Variable for error message
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Get leave record details
    SELECT 
        employee_id, 
        leave_type_id, 
        days_used, 
        applied_start_date, 
        status,
        YEAR(applied_start_date)
    INTO 
        v_employee_id, 
        v_leave_type_id, 
        v_days_used, 
        v_applied_start_date, 
        v_current_status,
        v_leave_year
    FROM leave_record 
    WHERE leave_record_id = v_leave_record_id;
    
    -- Check if leave record exists
    IF v_employee_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Leave record not found';
    END IF;
    
    -- Check if leave is already approved or rejected
    IF v_current_status != 'PENDING' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Leave record is already processed';
    END IF;
    
    -- Get employee's entitlement for this leave type and year
    SELECT entitlement_days 
    INTO v_entitlement_days
    FROM leave_entitlement 
    WHERE employee_id = v_employee_id 
        AND leave_type_id = v_leave_type_id 
        AND year = v_leave_year;
    
    -- Check if entitlement exists
    IF v_entitlement_days IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No leave entitlement found for this employee, leave type, and year';
    END IF;
    
    -- Calculate already used days for this leave type and year (excluding current record)
    SELECT COALESCE(SUM(days_used), 0)
    INTO v_already_used_days
    FROM leave_record 
    WHERE employee_id = v_employee_id 
        AND leave_type_id = v_leave_type_id 
        AND YEAR(applied_start_date) = v_leave_year
        AND status = 'APPROVED'
        AND leave_record_id != v_leave_record_id;
    
    -- Calculate remaining days
    SET v_remaining_days = v_entitlement_days - v_already_used_days;

    -- Check if employee has enough remaining days
    IF v_days_used > v_remaining_days THEN
        SET v_error_message = CONCAT('Insufficient leave balance. Requested: ', v_days_used, ' days, Available: ', v_remaining_days, ' days');
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_error_message;
    END IF;
    
    -- Approve the leave
    UPDATE leave_record
    SET 
        status = 'APPROVED',
        remarks = v_remarks,
        status_updated_by = v_approved_by,
        status_updated_at = NOW()
    WHERE leave_record_id = v_leave_record_id;
    
    -- Check if update was successful
    SET v_affected_rows = ROW_COUNT();
    
    IF v_affected_rows = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Failed to approve leave record';
    END IF;
    
    -- Return updated record with balance information
    SELECT 
        lr.leave_record_id,
        lr.employee_id,
        lr.leave_type_id,
        lt.name AS leave_type_name,
        lr.application_date,
        lr.applied_start_date,
        lr.applied_end_date,
        lr.days_used,
        lr.reason,
        lr.status,
        lr.status_updated_by,
        lr.status_updated_at,
        lr.remarks,
        v_entitlement_days AS total_entitlement,
        (v_already_used_days + lr.days_used) AS total_used_days,
        (v_entitlement_days - v_already_used_days - lr.days_used) AS remaining_days
    FROM leave_record lr
    INNER JOIN leave_type lt ON lr.leave_type_id = lt.leave_type_id
    WHERE lr.leave_record_id = v_leave_record_id;
    
    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
