CREATE DEFINER=`root`@`localhost` PROCEDURE `CloseClockHourRecordByEmployee`(
    IN v_employee_id INT
)
BEGIN
    -- Variables
    DECLARE v_clock_in_time DATETIME;
    DECLARE v_clock_out_time DATETIME; -- Changed to DATETIME
    DECLARE v_affected_rows INT DEFAULT 0;

    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Start transaction
    START TRANSACTION;

    -- Find the most recent unclosed record for this employee
    SELECT clock_in_time
    INTO v_clock_in_time
    FROM clock_hour
    WHERE employee_id = v_employee_id
      AND clock_out_time IS NULL
    ORDER BY clock_in_time DESC
    LIMIT 1;

    -- Check if unclosed record exists
    IF v_clock_in_time IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No unclosed clock hour record found for this employee';
    END IF;

    -- Set the current clock-out time
    SET v_clock_out_time = NOW(); -- Assign current timestamp

    -- Update the record
    UPDATE clock_hour
    SET
        clock_out_time = v_clock_out_time
    WHERE employee_id = v_employee_id
      AND clock_in_time = v_clock_in_time
      AND clock_out_time IS NULL;

    -- Check if update was successful
    SET v_affected_rows = ROW_COUNT();

    IF v_affected_rows = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Failed to close clock hour record';
    END IF;

    -- Return updated record
    SELECT
        clock_hour_id,
        employee_id,
        clock_in_time,
        clock_out_time,
        hours_worked
    FROM clock_hour
    WHERE employee_id = v_employee_id
      AND clock_in_time = v_clock_in_time; -- Use only clock_in_time and employee_id for reliable lookup

    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
