CREATE DEFINER=`root`@`localhost` PROCEDURE `CreateClockHourRecord`(
    IN v_employee_id INT,
    IN v_clock_in_time DATETIME,
    IN v_clock_out_time DATETIME
)
BEGIN
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;

    -- Check if employee_id exists
    IF NOT EXISTS (SELECT 1 FROM employee WHERE employee_id = v_employee_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Employee ID does not exist. Please provide a valid employee ID.';
    END IF;
    
        -- Validate that clock_out is after clock_in
        IF v_clock_out_time IS NOT NULL THEN
			IF v_clock_out_time <= v_clock_in_time THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Clock out time must be after clock in time';
			END IF;
        END IF;
    
    -- Check if the employee has already clocked in today
    IF EXISTS (
        SELECT 1
        FROM clock_hour
        WHERE employee_id = v_employee_id
        AND DATE(clock_in_time) = DATE(v_clock_in_time)
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Employee has already clocked in for today';
    END IF;

    -- Insert the record
    INSERT INTO clock_hour (
        employee_id,
        clock_in_time,
        clock_out_time
    ) VALUES (
        v_employee_id,
        v_clock_in_time,
        v_clock_out_time
    );
    
    -- Return the created record ID
    SELECT LAST_INSERT_ID() AS clock_hour_id;
    
    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
