CREATE DEFINER=`root`@`localhost` PROCEDURE `CreateEmployeeRecord`(
    -- Employee Table variables
    IN first_name varchar(50),
    IN last_name varchar(50),
    IN gender enum('MALE','FEMALE'),
    IN birthday date,
    IN phone_number varchar(15),
    IN sss_number varchar(15),
    IN philhealth_number varchar(15),
    IN tin_number varchar(15),
    IN pagibig_number varchar(15),
    IN employment_status enum('REGULAR','PROBATIONARY'),
    IN department enum('HUMAN_RESOURCES','INFORMATION_TECHNOLOGY','FINANCE','SALES_AND_MARKETING','SUPPLY_CHAIN_AND_LOGISTICS','CUSTOMER_SERVICE','OPERATIONS'),
    IN supervisor_id int,

    -- PositionSalaryHistory Table variables
    IN job_title varchar(255),  -- Changed from position_id to job_title
    IN job_description text,    -- Optional job description
    IN basic_salary decimal(10,2),
    IN rice_subsidy decimal(10,2),
    IN phone_allowance decimal(10,2),
    IN clothing_allowance decimal(10,2),

    -- Address Table variables
    IN building_street varchar(255),
    IN barangay varchar(100),
    IN city_municipality varchar(100),
    IN province varchar(100),
    IN zipcode varchar(10),

    -- EmployeeAddress Table variables
    IN address_type enum('HOME','EMERGENCY'),

    -- UserCredential Table variables
    IN password varchar(255),
    IN user_role enum('EMPLOYEE','ADMIN','HR','IT','FINANCE')
)
BEGIN
    DECLARE address_id INT;
    DECLARE position_salary_id INT;
    DECLARE new_employee_id INT;
    DECLARE existing_position_id INT DEFAULT NULL;
    DECLARE supervisor_exists BOOLEAN DEFAULT FALSE;

    -- Error handling variables
    DECLARE exit handler for sqlexception
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Start transaction
    START TRANSACTION;

    -- Pre-check: Validate supervisor_id if provided
    IF supervisor_id IS NOT NULL THEN
        SELECT TRUE INTO supervisor_exists
        FROM employee
        WHERE employee_id = supervisor_id;

        IF NOT supervisor_exists THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Please enter an existing Employee ID for the Supervisor ID, or leave it blank.';
        END IF;
    END IF;

    -- Step 1: Check if job position already exists (case-insensitive)
    SELECT position_id INTO existing_position_id
    FROM job_position
    WHERE UPPER(TRIM(title)) = UPPER(TRIM(job_title))
    LIMIT 1;

    -- Step 2: If position doesn't exist, create it
    IF existing_position_id IS NULL THEN
        INSERT INTO job_position (title, description)
        VALUES (TRIM(job_title), job_description);

        SET existing_position_id = LAST_INSERT_ID();
    END IF;

    -- Step 3: Insert into Address table
    INSERT INTO address (building_street,
                         barangay,
                         city_municipality,
                         province,
                         zipcode)
    VALUES (building_street,
            barangay,
            city_municipality,
            province,
            zipcode);

    -- Get the last inserted address ID
    SET address_id = LAST_INSERT_ID();

    -- Step 4: Insert into PositionSalaryHistory table
    -- Note: employee_id is set to NULL initially as it's not yet known.
    -- It will be updated in Step 7 after the employee record is created.
    INSERT INTO position_salary_history (position_id,
                                         basic_salary,
                                         rice_subsidy,
                                         phone_allowance,
                                         clothing_allowance,
                                         effective_start_date,
                                         effective_end_date)
    VALUES (existing_position_id,
            basic_salary,
            rice_subsidy,
            phone_allowance,
            clothing_allowance,
            CURDATE(),
            NULL);

    -- Get the last inserted position salary ID
    SET position_salary_id = LAST_INSERT_ID();

    -- Step 5: Insert into Employee table
    INSERT INTO employee (first_name,
                          last_name,
                          gender,
                          birthday,
                          phone_number,
                          sss_number,
                          philhealth_number,
                          tin_number,
                          pagibig_number,
                          employment_status,
                          department,
                          supervisor_id,
                          position_salary_history_id)
    VALUES (first_name,
            last_name,
            gender,
            birthday,
            phone_number,
            sss_number,
            philhealth_number,
            tin_number,
            pagibig_number,
            employment_status,
            department,
            supervisor_id,
            position_salary_id);

    -- Get the last inserted employee ID
    SET new_employee_id = LAST_INSERT_ID();

    -- Step 6: Insert into EmployeeAddress table
    INSERT INTO employee_address (employee_id,
                                  address_id,
                                  address_type)
    VALUES (new_employee_id,
            address_id,
            address_type);

    -- Step 7: Update Employee ID on PositionSalaryHistory table
    -- This step links the newly created employee to their salary history.
    UPDATE position_salary_history
    SET employee_id = new_employee_id
    WHERE position_salary_history_id = position_salary_id;

    -- Step 8: Insert into UserCredential table
    INSERT INTO user_credential (employee_id,
                                 password,
                                 user_role)
    VALUES (new_employee_id,
            password,
            user_role);

    -- Commit transaction if all steps succeed
    COMMIT;

END ;;
DELIMITER ;
