CREATE DEFINER=`root`@`localhost` PROCEDURE `CreateLeaveRecord`(
    IN v_employee_id INT,
    IN v_leave_type_id INT,
    IN v_application_date DATE,
    IN v_applied_start_date DATE,
    IN v_applied_end_date DATE,
    IN v_days_used INT,
    IN v_reason TEXT
)
BEGIN
    -- Variables
    DECLARE v_leave_record_id INT;
    DECLARE v_overlap_count INT DEFAULT 0;
    DECLARE v_leave_year INT;
    DECLARE v_entitlement_days INT DEFAULT 0;
    DECLARE v_already_used_days INT DEFAULT 0;
    DECLARE v_remaining_days INT DEFAULT 0;
    DECLARE v_error_message TEXT; -- Variable for error message
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Get the leave year from the applied start date
    SET v_leave_year = YEAR(v_applied_start_date);
    
    -- Validate dates
    IF v_applied_end_date < v_applied_start_date THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'End date must be after or equal to start date';
    END IF;
    
    -- Validate leave type exists and is active
    IF NOT EXISTS (SELECT 1 FROM leave_type WHERE leave_type_id = v_leave_type_id AND is_active = 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid or inactive leave type';
    END IF;
    
        -- Check for overlapping leave requests
    SELECT COUNT(*) INTO v_overlap_count
    FROM leave_record 
    WHERE employee_id = v_employee_id 
    AND status IN ('PENDING', 'APPROVED')
    AND (
        (v_applied_start_date BETWEEN applied_start_date AND applied_end_date) OR
        (v_applied_end_date BETWEEN applied_start_date AND applied_end_date) OR
        (applied_start_date BETWEEN v_applied_start_date AND v_applied_end_date) OR
        (applied_end_date BETWEEN v_applied_start_date AND v_applied_end_date)
    );
    
    IF v_overlap_count > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'You have overlapping leave requests for the selected dates';
    END IF;
    
    -- Get employee's entitlement for this leave type and year
    SELECT entitlement_days 
    INTO v_entitlement_days
    FROM leave_entitlement 
    WHERE employee_id = v_employee_id 
        AND leave_type_id = v_leave_type_id 
        AND year = v_leave_year;
    
    -- Check if entitlement exists
    IF v_entitlement_days IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No leave entitlement found for this employee, leave type, and year';
    END IF;
    
    -- Calculate already used days for this leave type and year
    SELECT COALESCE(SUM(days_used), 0)
    INTO v_already_used_days
    FROM leave_record 
    WHERE employee_id = v_employee_id 
        AND leave_type_id = v_leave_type_id 
        AND YEAR(applied_start_date) = v_leave_year
        AND status = 'APPROVED';
    
    -- Calculate remaining days
    SET v_remaining_days = v_entitlement_days - v_already_used_days;

    -- Check if employee has enough remaining days
    IF v_days_used > v_remaining_days THEN
        SET v_error_message = CONCAT('Insufficient leave balance. Requested: ', v_days_used, ' days, Available: ', v_remaining_days, ' days');
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_error_message;
    END IF;
    
    -- Insert the leave record
    INSERT INTO leave_record (
        employee_id,
        leave_type_id,
        application_date,
        applied_start_date,
        applied_end_date,
        days_used,
        reason,
        status
    ) VALUES (
        v_employee_id,
        v_leave_type_id,
        v_application_date,
        v_applied_start_date,
        v_applied_end_date,
        v_days_used,
        v_reason,
        'PENDING'
    );
    
    -- Get the created record ID
    SET v_leave_record_id = LAST_INSERT_ID();
    
	-- Return the created record with balance information
		SELECT 
			lr.leave_record_id,
			lr.employee_id,
			lr.leave_type_id,
			lt.name AS leave_type_name,
			lr.application_date,
			lr.applied_start_date,
			lr.applied_end_date,
			lr.days_used,
			lr.reason,
			lr.status,
			lr.status_updated_by,
			lr.status_updated_at,
			lr.remarks,
			v_entitlement_days AS total_entitlement,
			(v_already_used_days + lr.days_used) AS total_used_days,
			(v_entitlement_days - v_already_used_days - lr.days_used) AS remaining_days
		FROM leave_record lr
		INNER JOIN leave_type lt ON lr.leave_type_id = lt.leave_type_id
		WHERE lr.leave_record_id = v_leave_record_id;
    
    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
