CREATE DEFINER=`root`@`localhost` PROCEDURE `DeleteClockHourRecord`(
	IN v_clock_hour_id INT)
BEGIN
-- Variables
    DECLARE v_affected_rows INT DEFAULT 0;
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Delete the record
    DELETE FROM clock_hour
    WHERE clock_hour_id = v_clock_hour_id;
    
    -- Check if deletion was successful
    SET v_affected_rows = ROW_COUNT();
    
    IF v_affected_rows = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Clock hour record not found or already deleted';
    END IF;
    
    -- Return success message
    SELECT 'Clock hour record deleted successfully' AS message, v_affected_rows AS rows_affected;
    
    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
