CREATE DEFINER=`root`@`localhost` PROCEDURE `DeleteLeaveRecord`(
    IN v_leave_record_id INT
)
BEGIN
    -- Variables
    DECLARE v_affected_rows INT DEFAULT 0;
    DECLARE v_record_status ENUM('PENDING','APPROVED','REJECTED');
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Check if record exists and get its status
    SELECT status INTO v_record_status
    FROM leave_record
    WHERE leave_record_id = v_leave_record_id;
    
    IF v_record_status IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Leave record not found';
    END IF;
    
    -- Optional: Prevent deletion of approved records (uncomment if needed)
    -- IF v_record_status = 'APPROVED' THEN
    --     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot delete approved leave records';
    -- END IF;
    
    -- Delete the record
    DELETE FROM leave_record
    WHERE leave_record_id = v_leave_record_id;
    
    -- Check if deletion was successful
    SET v_affected_rows = ROW_COUNT();
    
    -- Return success message
    SELECT 'Leave record deleted successfully' AS message, v_affected_rows AS rows_affected;
    
    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
