CREATE DEFINER=`root`@`localhost` PROCEDURE `FindAllLeaveRecords`()
BEGIN
    -- Error handling block: If any SQL exception occurs, re-signal the error.
    -- This ensures that any underlying database errors are passed back to the caller.
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;

    -- Select all relevant columns from the leave_record table (aliased as lr).
    -- It joins with the leave_type table (aliased as lt) to fetch the human-readable
    -- name of the leave type, rather than just the ID.
    SELECT
        lr.leave_record_id,         -- Unique identifier for the leave application
        lr.employee_id,             -- ID of the employee who applied
        lr.leave_type_id,           -- ID of the type of leave
        lt.name AS leave_type_name, -- Name of the leave type (e.g., 'Vacation', 'Sick')
        lr.application_date,        -- Date when the application was submitted
        lr.applied_start_date,      -- Start date of the requested leave period
        lr.applied_end_date,        -- End date of the requested leave period
        lr.days_used,               -- Number of days requested for leave
        lr.reason,                  -- Reason provided by the employee
        lr.status,                  -- Current status of the application ('PENDING', 'APPROVED', 'REJECTED')
        lr.status_updated_by,       -- ID of the user who last updated the status
        lr.status_updated_at,       -- Timestamp when the status was last updated
        lr.remarks                  -- Any remarks added during status update
    FROM
        leave_record lr
    INNER JOIN
        leave_type lt ON lr.leave_type_id = lt.leave_type_id
    ORDER BY
        lr.application_date DESC,   -- Order by application date, most recent first
        lr.leave_record_id DESC;    -- Then by record ID to ensure consistent ordering for same-day applications
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
