CREATE DEFINER=`root`@`localhost` PROCEDURE `FindApprovedLeavesByEmployeeByPayPeriod`(
    IN v_employee_id INT,
    IN v_start_date DATE,
    IN v_end_date DATE
)
BEGIN
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;
    
    SELECT 
        lr.leave_record_id,
        lr.employee_id,
        lr.leave_type_id,
        lt.name AS leave_type_name,
        lr.application_date,
        lr.applied_start_date,
        lr.applied_end_date,
        lr.days_used,
        lr.reason,
        lr.status,
        lr.status_updated_by,
        lr.status_updated_at,
        lr.remarks
    FROM leave_record lr
    INNER JOIN leave_type lt ON lr.leave_type_id = lt.leave_type_id
    WHERE lr.employee_id = v_employee_id
        AND lr.status = 'APPROVED'
        AND (
            (lr.applied_start_date BETWEEN v_start_date AND v_end_date)
            OR (lr.applied_end_date BETWEEN v_start_date AND v_end_date)
            OR (lr.applied_start_date <= v_start_date AND lr.applied_end_date >= v_end_date)
        )
    ORDER BY lr.applied_start_date;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
