    IN v_employee_id INT
)
BEGIN
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;
    
    SELECT 
        clock_hour_id,
        employee_id,
        clock_in_time,
        clock_out_time,
        hours_worked,
        CASE 
            WHEN clock_out_time IS NULL THEN 'OPEN'
            ELSE 'CLOSED'
        END AS record_status
