CREATE DEFINER=`root`@`localhost` PROCEDURE `FindClockHoursByEmployeeIdAndPayPeriod`(
    IN v_employee_id INT,
    IN v_start_date DATE,
    IN v_end_date DATE
)
BEGIN
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;
    
    SELECT 
        clock_hour_id,
        employee_id,
        clock_in_time,
        clock_out_time,
        hours_worked,
        CASE 
            WHEN clock_out_time IS NULL THEN 'OPEN'
            ELSE 'CLOSED'
        END AS record_status
    FROM clock_hour
    WHERE employee_id = v_employee_id
      AND DATE(clock_in_time) BETWEEN v_start_date AND v_end_date
    ORDER BY clock_in_time DESC;
END ;;
