CREATE DEFINER=`root`@`localhost` PROCEDURE `FindEmployeeById`(
    IN emp_id INT
)
BEGIN
    -- Error handling
    DECLARE exit handler for sqlexception
    BEGIN
        RESIGNAL;
    END;
    
    -- Validate input parameter
    IF emp_id IS NULL OR emp_id <= 0 THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'Invalid employee ID provided';
    END IF;
    
    SELECT 
        e.employee_id,
        e.first_name,
        e.last_name,
        e.gender,
        e.birthday,
        e.phone_number,
        e.sss_number,
        e.philhealth_number,
        e.tin_number,
        e.pagibig_number,
        e.employment_status,
        e.department,
        e.supervisor_id,
        e.position_salary_history_id,
        
        -- Position and Salary Information
        psh.position_id,
        jp.title as job_title,
        jp.description as job_description,
        psh.basic_salary,
        psh.rice_subsidy,
        psh.phone_allowance,
        psh.clothing_allowance,
        psh.effective_start_date,
        psh.effective_end_date,
        
        -- Address Information
        a.address_id,
        a.building_street,
        a.barangay,
        a.city_municipality,
        a.province,
        a.zipcode,
        ea.address_type,
        
        -- User Credential Information
        uc.password,
        uc.user_role
        
    FROM employee e
    LEFT JOIN position_salary_history psh ON e.position_salary_history_id = psh.position_salary_history_id
    LEFT JOIN job_position jp ON psh.position_id = jp.position_id
    LEFT JOIN employee_address ea ON e.employee_id = ea.employee_id
    LEFT JOIN address a ON ea.address_id = a.address_id
    LEFT JOIN user_credential uc ON e.employee_id = uc.employee_id
    WHERE e.employee_id = emp_id;
    
END ;;
DELIMITER ;
