CREATE DEFINER=`root`@`localhost` PROCEDURE `FindLeaveEntitlementById`(
    IN v_leave_entitlement_id INT
)
BEGIN
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;
    
    SELECT 
        le.leave_entitlement_id,
        le.employee_id,
        le.leave_type_id,
        lt.name AS leave_type_name,
        le.entitlement_days,
        le.year
    FROM leave_entitlement le
    INNER JOIN leave_type lt ON le.leave_type_id = lt.leave_type_id
    WHERE le.leave_entitlement_id = v_leave_entitlement_id;
END ;;
DELIMITER ;
