/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `FindLeaveEntitlementsByEmployeeIdAndYear`(
    IN v_employee_id INT,
    IN v_year INT
)
BEGIN
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;
    
    SELECT 
        le.leave_entitlement_id,
        le.employee_id,
        le.leave_type_id,
        lt.name AS leave_type_name,
        le.entitlement_days,
        le.year,
        COALESCE(SUM(lr.days_used), 0) AS days_used,
        (le.entitlement_days - COALESCE(SUM(lr.days_used), 0)) AS remaining_days
    FROM leave_entitlement le
    INNER JOIN leave_type lt ON le.leave_type_id = lt.leave_type_id
    LEFT JOIN leave_record lr ON le.employee_id = lr.employee_id 
        AND le.leave_type_id = lr.leave_type_id 
        AND YEAR(lr.applied_start_date) = le.year
        AND lr.status = 'APPROVED'
    WHERE le.employee_id = v_employee_id 
        AND le.year = v_year
    GROUP BY le.leave_entitlement_id, le.employee_id, le.leave_type_id, 
             lt.name, le.entitlement_days, le.year
    ORDER BY lt.name;
END ;;
DELIMITER ;
