CREATE DEFINER=`root`@`localhost` PROCEDURE `FindUnclosedClockHourByEmployee`(
    IN v_employee_id INT
)
BEGIN
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        RESIGNAL;
    END;
    
    SELECT 
        clock_hour_id,
        employee_id,
        clock_in_time,
        clock_out_time,
        hours_worked
    FROM clock_hour
    WHERE employee_id = v_employee_id
      AND clock_out_time IS NULL
    ORDER BY clock_in_time DESC;
END ;;
