/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerateAndRecordPayslip`(
    IN p_employee_id INT,
    IN p_pay_period_start DATE,
    IN p_pay_period_end DATE
)
BEGIN 
    -- Declaring all the variables needed to store calculated values for the payslip (e.g., income, benefits, and various deductions).
    DECLARE v_pay_period_id INT;
    DECLARE v_position_salary_history_id INT;
    DECLARE v_hourly_rate DECIMAL(10, 2);
    DECLARE v_basic_salary DECIMAL(10, 2); -- Added this variable, as deductions like SSS/PhilHealth/Pag-IBIG typically rely on basic salary.
    DECLARE v_rice_subsidy DECIMAL(10, 2);
    DECLARE v_phone_allowance DECIMAL(10, 2);
    DECLARE v_clothing_allowance DECIMAL(10, 2);
    DECLARE v_total_regular_hours DECIMAL(10, 2);
    DECLARE v_days_worked INT;
    DECLARE v_total_overtime_hours DECIMAL(10, 2);
    DECLARE v_paid_leave_days DECIMAL(10, 2); -- Currently unimplemented
    DECLARE v_overtime_rate_multiplier DECIMAL(4, 2); -- Variable for applying the correct overtime pay rate.
    DECLARE v_gross_income DECIMAL(10, 2);
    DECLARE v_total_benefits DECIMAL(10, 2);
    DECLARE v_sss_contribution DECIMAL(10, 2);
    DECLARE v_philhealth_contribution DECIMAL(10, 2);
    DECLARE v_pagibig_contribution DECIMAL(10, 2);
    DECLARE v_taxable_income DECIMAL(10, 2); -- Represents gross income after subtracting non-taxable contributions.
    DECLARE v_withholding_tax DECIMAL(10, 2);
    DECLARE v_total_deductions DECIMAL(10, 2);
    DECLARE v_net_income DECIMAL(10, 2);
    DECLARE v_tax_and_deduction_id INT;
    DECLARE v_payslip_id INT;

    -- Setting a default multiplier for overtime pay (e.g., 1.25 for 125% of the hourly rate). This can be adjusted based on policy.
    SET v_overtime_rate_multiplier = 1.25;

    -- 1. Handling the Pay Period: Checking if the pay period already exists in the database; if not, creating a new record for it.
    SELECT pay_period_id INTO v_pay_period_id
    FROM pay_period
    WHERE start_date = p_pay_period_start AND end_date = p_pay_period_end;

    IF v_pay_period_id IS NULL THEN
        INSERT INTO pay_period (start_date, end_date)
        VALUES (p_pay_period_start, p_pay_period_end);
        SET v_pay_period_id = LAST_INSERT_ID();
    END IF;

    -- 2. Retrieving the employee's most recent position, salary, and allowance details.
    -- This includes their hourly rate and the basic salary, which is essential for accurate deduction calculations.
    -- The query ensures that the salary history fetched is effective on or before the end of the current pay period.
    SELECT
        psh.position_salary_history_id,
        COALESCE(psh.hourly_rate, 0),
        COALESCE(psh.basic_salary, 0), -- Fetching the basic salary.
        COALESCE(psh.rice_subsidy, 0),
        COALESCE(psh.phone_allowance, 0),
        COALESCE(psh.clothing_allowance, 0)
    INTO
        v_position_salary_history_id,
        v_hourly_rate,
        v_basic_salary, -- Assigning the fetched basic salary to its variable.
        v_rice_subsidy,
        v_phone_allowance,
        v_clothing_allowance
    FROM
        position_salary_history psh
    WHERE
        psh.employee_id = p_employee_id
        AND psh.effective_start_date <= p_pay_period_end -- Ensuring the correct salary history effective for this specific pay period.
    ORDER BY
        psh.effective_start_date DESC -- Selecting the latest applicable salary record.
    LIMIT 1;

    -- Error handling: If no salary history is found, an error is signaled as payslip generation is not possible.
    IF v_position_salary_history_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Employee position or salary history not found for the given employee ID and pay period.';
    END IF;

    -- 3. Calculate regular hours worked, unique days worked, overtime hours, and paid leave days for the employee within the pay period.
    SELECT
		COALESCE(SUM(CASE 
			WHEN ch.hours_worked > 8 THEN 8 
			ELSE ch.hours_worked 
		END), 0) AS total_regular_hours,
		
		COALESCE(SUM(CASE 
			WHEN ch.hours_worked > 8 THEN ch.hours_worked - 8 
			ELSE 0 
		END), 0) AS total_overtime_hours,
		
		COALESCE(COUNT(DISTINCT DATE(ch.clock_in_time)), 0) AS days_worked,
		
		COALESCE(SUM(CASE 
			WHEN lr.status = 'APPROVED' AND DATE(ch.clock_in_time) BETWEEN lr.applied_start_date AND lr.applied_end_date THEN 1 
			ELSE 0 
		END), 0) AS paid_leave_days
	INTO
		v_total_regular_hours,
		v_total_overtime_hours,
		v_days_worked,
		v_paid_leave_days
	FROM
		clock_hour ch
	LEFT JOIN
		leave_record lr ON ch.employee_id = lr.employee_id
		AND lr.status = 'APPROVED' 
		AND DATE(ch.clock_in_time) BETWEEN lr.applied_start_date AND lr.applied_end_date
	WHERE
		ch.employee_id = p_employee_id
		AND ch.clock_in_time BETWEEN p_pay_period_start AND p_pay_period_end;

	-- 4. Calculating Gross Income: This involves summing regular pay (total regular hours at hourly rate)
	-- and overtime pay (total overtime hours at the hourly rate multiplied by the overtime rate factor).
	SET v_gross_income = ROUND(
		(v_total_regular_hours * v_hourly_rate) + -- This is the pay for regular hours
		(v_total_overtime_hours * v_hourly_rate * v_overtime_rate_multiplier), -- This is the pay for overtime hours
		2
	);

    -- 5. Benefits Calculation: Summing all applicable allowances (rice, phone, clothing) to get total benefits.
    SET v_total_benefits = ROUND(v_rice_subsidy + v_phone_allowance + v_clothing_allowance, 2);

    -- 6. Deductions Calculation (SSS, PhilHealth, Pag-IBIG): These contributions are calculated based on the employee's basic salary.

    -- SSS Contribution: Determining the SSS contribution based on the basic salary and the applicable rate history.
    SELECT COALESCE(sss.contribution, 0) INTO v_sss_contribution
    FROM sss_rates_history sss
    WHERE
        v_basic_salary BETWEEN COALESCE(sss.min_amount, -999999999.99) AND COALESCE(sss.max_amount, 999999999.99) -- Using basic salary for range lookup.
        AND p_pay_period_end BETWEEN sss.effective_start_date AND COALESCE(sss.effective_end_date, '9999-12-31') -- Ensuring the rate is effective for the pay period.
    LIMIT 1;

    -- PhilHealth Contribution: FIXED - Calculating PhilHealth premium based on the basic salary and relevant tiers/rates.
    SELECT ROUND(
        (
            CASE
                WHEN v_basic_salary IS NULL OR v_basic_salary <= 0 THEN 0
                WHEN v_basic_salary <= 10000.00 THEN (10000.00 * COALESCE(pr.premium_rate, 0) / 100) / 2
                WHEN v_basic_salary >= 60000.00 THEN (60000.00 * COALESCE(pr.premium_rate, 0) / 100) / 2
                WHEN v_basic_salary BETWEEN 10000.01 AND 59999.99 THEN (v_basic_salary * COALESCE(pr.premium_rate, 0) / 100) / 2
                ELSE 0 -- Fallback case
            END
        ), 2
    ) INTO v_philhealth_contribution
    FROM philhealth_rates_history pr
    WHERE
        v_basic_salary BETWEEN COALESCE(pr.min_amount, -999999999.99) AND COALESCE(pr.max_amount, 999999999.99)
        AND p_pay_period_end BETWEEN pr.effective_start_date AND COALESCE(pr.effective_end_date, '9999-12-31')
    LIMIT 1;

    -- Pag-IBIG Contribution: FIXED - Using the total_contribution directly from the table (which already has the 100 peso cap applied)
    SELECT ROUND(
        LEAST(
            v_basic_salary * COALESCE(pi.employee_rate, 0) / 100,
            100.00
        ), 2
    ) INTO v_pagibig_contribution
    FROM pagibig_rates_history pi
    WHERE
        v_basic_salary BETWEEN COALESCE(pi.min_amount, -999999999.99) AND COALESCE(pi.max_amount, 999999999.99) -- Using basic salary for range lookup.
        AND p_pay_period_end BETWEEN pi.effective_start_date AND COALESCE(pi.effective_end_date, '9999-12-31') -- Ensuring the rate is effective for the pay period.
    LIMIT 1;

    -- 7. Calculating Taxable Income: FIXED - This is derived by subtracting the non-taxable SSS, PhilHealth, and Pag-IBIG contributions from the GROSS INCOME.
    SET v_taxable_income = ROUND(v_gross_income - (v_sss_contribution + v_philhealth_contribution + v_pagibig_contribution), 2);

    -- 8. Determining Withholding Tax:
    SELECT ROUND(
        (
            CASE
                WHEN v_taxable_income IS NULL OR v_taxable_income <= 0 THEN 0
                WHEN tr.min_amount = 0 THEN 0 -- First bracket (0% tax)
                ELSE
                    COALESCE(tr.fixed_amount, 0) + ((v_taxable_income - tr.min_amount) * COALESCE(tr.tax_rate, 0) / 100)
            END
        ), 2
    ) INTO v_withholding_tax
    FROM tax_rates_history tr
    WHERE
        v_taxable_income BETWEEN COALESCE(tr.min_amount, -999999999.99) AND COALESCE(tr.max_amount, 999999999.99) -- Based on taxable income for range lookup.
        AND p_pay_period_end BETWEEN tr.effective_start_date AND COALESCE(tr.effective_end_date, '9999-12-31') -- Ensuring the rate is effective for the pay period.
    LIMIT 1;

    -- 9. Calculating Total Deductions: Summing up all mandatory deductions: SSS, PhilHealth, Pag-IBIG, and Withholding Tax.
    SET v_total_deductions = ROUND(v_sss_contribution + v_philhealth_contribution + v_pagibig_contribution + v_withholding_tax, 2);

    -- 10. Creating the Tax and Deduction Record: Inserting all calculated deduction figures into the `tax_and_deduction` table.
    -- The rate IDs are linked using the basic salary for SSS, PhilHealth, and Pag-IBIG lookups to maintain accuracy.
    INSERT INTO tax_and_deduction (
        sss_rate_id, philhealth_rate_id, pagibig_rate_id, tax_rate_id,
        total_deductions, payslip_id,
        sss_contribution,
        philhealth_contribution,
        pagibig_contribution,
        withholding_tax
    ) VALUES (
        (SELECT sss_rate_id FROM sss_rates_history WHERE v_basic_salary BETWEEN COALESCE(min_amount, -999999999.99) AND COALESCE(max_amount, 999999999.99) AND p_pay_period_end BETWEEN effective_start_date AND COALESCE(effective_end_date, '9999-12-31') LIMIT 1), -- Using basic salary for SSS rate ID.
        (SELECT philhealth_rate_id FROM philhealth_rates_history WHERE v_basic_salary BETWEEN COALESCE(min_amount, -999999999.99) AND COALESCE(max_amount, 999999999.99) AND p_pay_period_end BETWEEN effective_start_date AND COALESCE(effective_end_date, '9999-12-31') LIMIT 1), -- Using basic salary for PhilHealth rate ID.
        (SELECT pagibig_rate_id FROM pagibig_rates_history WHERE v_basic_salary BETWEEN COALESCE(min_amount, -999999999.99) AND COALESCE(max_amount, 999999999.99) AND p_pay_period_end BETWEEN effective_start_date AND COALESCE(effective_end_date, '9999-12-31') LIMIT 1), -- Using basic salary for Pag-IBIG rate ID.
        (SELECT tax_rate_id FROM tax_rates_history WHERE v_taxable_income BETWEEN COALESCE(min_amount, -999999999.99) AND COALESCE(max_amount, 999999999.99) AND p_pay_period_end BETWEEN effective_start_date AND COALESCE(effective_end_date, '9999-12-31') LIMIT 1),
        v_total_deductions,
        NULL,
        v_sss_contribution,
		v_philhealth_contribution,
        v_pagibig_contribution,
		v_withholding_tax
    );
    SET v_tax_and_deduction_id = LAST_INSERT_ID();

    -- 11. Calculating Net Income: This is the final take-home pay, derived by adding total benefits to gross income and then subtracting total deductions.
    SET v_net_income = ROUND(v_gross_income + v_total_benefits - v_total_deductions, 2);

    -- 12. Creating the Payslip Record: Inserting all computed figures into the `payslip` table, referencing the associated tax and deduction record.
    INSERT INTO payslip (
        employee_id, pay_period_id, days_worked, total_hours_worked, total_overtime_hours,
        gross_income, total_benefits, tax_and_deduction_id, net_income, date_generated
    ) VALUES (
        p_employee_id, v_pay_period_id, v_days_worked, v_total_regular_hours, v_total_overtime_hours,
        v_gross_income, v_total_benefits, v_tax_and_deduction_id, v_net_income, CURDATE()
    );
    SET v_payslip_id = LAST_INSERT_ID();

    -- 13. Updating the Tax and Deduction Record: Linking the newly created payslip to its corresponding tax and deduction record.
    UPDATE tax_and_deduction
    SET payslip_id = v_payslip_id
    WHERE tax_and_deduction_id = v_tax_and_deduction_id;

    -- Final step: Selecting all the relevant details to display the newly generated payslip for verification purposes.
    SELECT
        p_employee_id AS Employee_ID,
        (SELECT CONCAT(first_name, ' ', last_name) FROM employee WHERE employee_id = p_employee_id) AS Employee_Name,
        p_pay_period_start AS Pay_Period_Start,
        p_pay_period_end AS Pay_Period_End,
        v_days_worked AS Distinct_Days_Worked,
        v_total_regular_hours AS Total_Hours_Worked,
        v_total_overtime_hours AS Overtime_Hours,
        v_hourly_rate AS Hourly_Rate,
        v_overtime_rate_multiplier AS Overtime_Rate_Multiplier,
        v_gross_income AS Gross_Income,
        v_total_benefits AS Total_Benefits,
        v_basic_salary AS Basic_Salary,
        v_sss_contribution AS SSS_Contribution,
        v_philhealth_contribution AS PhilHealth_Contribution,
        v_pagibig_contribution AS PagIBIG_Contribution,
        v_taxable_income AS Calculated_Taxable_Income,
        v_withholding_tax AS Withholding_Tax,
        v_total_deductions AS Total_Deductions,
        v_net_income AS Net_Income,
        v_payslip_id AS Generated_Payslip_ID,
        v_tax_and_deduction_id AS Generated_Tax_Deduction_ID;

END ;;
