CREATE DEFINER=`root`@`localhost` PROCEDURE `GetAllPayslipOfEmployee`(
    IN p_employee_id INT
)
BEGIN
    SELECT
        -- HEADER
        py.payslip_id AS "Payslip No.",
        e.employee_id AS "Employee ID",
        CONCAT(e.last_name, ', ' ,e.first_name) AS "Employee Name",
        pp.start_date AS "Period Start Date",
        pp.end_date AS "Period End Date",
        p.title AS "Employee Position",
        e.department AS "Employee Department",

        -- EARNINGS
        psh.basic_salary AS "Monthly Rate", -- Basic Salary AS Monthly Rate
        psh.hourly_rate * 8 AS "Daily Rate", -- Hourly Rate * 8 (Regular Philippine work hours)
        psh.hourly_rate AS "Hourly Rate",
        1.25 as "Overtime Rate Multiplier", -- Overtime Rate Multiplier as per Philippine law

        py.days_worked AS "Distinct Days Worked", -- Could have worked less than 8 hours; Counts only DISTINCT days worked
        py.total_hours_worked AS "Hours Worked", -- Regular Hours
        py.total_overtime_hours AS "Overtime Hours", -- Hours that exceeded 8

        py.gross_income AS "Gross Income", -- Gross Income = (Hours Worked * Hourly Rate) + (Overtime Hours * Hourly Rate * Overtime Rate Multiplier)


        -- BENEFITS
        psh.rice_subsidy AS "Rice Subsidy",
        psh.phone_allowance AS "Phone Allowance",
        psh.clothing_allowance AS "Clothing Allowance",

        py.total_benefits AS "Total Benefits",


        -- DEDUCTIONS
        tx.sss_contribution AS "Social Security System Contribution",
        tx.philhealth_contribution AS "PhilHealth Contribution",
        tx.pagibig_contribution AS "Pag-IBIG Contribution",
        py.gross_income - (tx.sss_contribution + tx.philhealth_contribution + tx.pagibig_contribution) AS "Taxable Income",
        tx.withholding_tax AS "Withholding Tax",

        tx.total_deductions AS "Total Deductions",

        -- SUMMARY
        py.net_income AS "Net Income / Take Home Pay"

    FROM
        employee e
    LEFT JOIN payslip py ON e.employee_id = py.employee_id
    LEFT JOIN pay_period pp ON py.pay_period_id = pp.pay_period_id
    LEFT JOIN position_salary_history psh ON e.employee_id = psh.employee_id
        AND psh.effective_start_date = (
            SELECT MAX(psh2.effective_start_date)
            FROM position_salary_history psh2
            WHERE psh2.employee_id = e.employee_id
            AND psh2.effective_start_date <= COALESCE(pp.end_date, CURDATE())
        ) -- Get the most recent salary history for the pay period
    LEFT JOIN job_position p ON psh.position_id = p.position_id
    LEFT JOIN tax_and_deduction tx ON py.tax_and_deduction_id = tx.tax_and_deduction_id
    WHERE e.employee_id = p_employee_id -- Qualified employee_id
    ORDER BY e.employee_id, pp.end_date DESC; -- Add ordering for better readability

END ;;
DELIMITER ;
