/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `GetMonthlyPayrollSummaryReport`(
    IN p_month INT,
    IN p_year INT
)
BEGIN
    -- Declare variables for the start and end dates of the specified month
    DECLARE start_of_month DATE;
    DECLARE end_of_month DATE;

    -- Calculate the first day of the given month and year
    SET start_of_month = CONCAT_WS('-', p_year, p_month, '01');
    -- Calculate the last day of the given month and year
    SET end_of_month = LAST_DAY(start_of_month);

    -- Create a Common Table Expression (CTE) to prepare the detailed payslip data for the report.
    WITH PayslipDetails AS (
        SELECT
            e.employee_id,
            CONCAT(e.last_name, ', ' ,e.first_name) AS full_name,
            -- Get the position title effective for the payslip's period
            COALESCE(jp.title, 'No Position') AS position_title,
            COALESCE(e.department, 'No Department') AS department_name,
            py.gross_income,
            e.sss_number,
            COALESCE(tx.sss_contribution, 0) AS sss_contribution,
            e.philhealth_number,
            COALESCE(tx.philhealth_contribution, 0) AS philhealth_contribution,
            e.pagibig_number,
            COALESCE(tx.pagibig_contribution, 0) AS pagibig_contribution,
            e.tin_number,
            ROUND(py.gross_income - (
                COALESCE(tx.sss_contribution, 0) +
                COALESCE(tx.philhealth_contribution, 0) +
                COALESCE(tx.pagibig_contribution, 0)
            ), 2) AS taxable_income_for_report,
            COALESCE(tx.withholding_tax, 0) AS withholding_tax,
            py.net_income
        FROM
            payslip py
        INNER JOIN
            pay_period pp ON py.pay_period_id = pp.pay_period_id
        INNER JOIN
            employee e ON py.employee_id = e.employee_id
        INNER JOIN
            -- Join to tax_and_deduction to get the pre-calculated deduction amounts
            tax_and_deduction tx ON py.tax_and_deduction_id = tx.tax_and_deduction_id
        LEFT JOIN
            -- Join to position_salary_history to get the salary record effective at the pay period end date
            position_salary_history psh ON e.employee_id = psh.employee_id
            AND psh.effective_start_date = (
                SELECT MAX(psh2.effective_start_date)
                FROM position_salary_history psh2
                WHERE psh2.employee_id = e.employee_id
                AND psh2.effective_start_date <= COALESCE(pp.end_date, CURDATE())
            )
        LEFT JOIN
            job_position jp ON psh.position_id = jp.position_id
        WHERE
            -- Filter payslips for the specified month and year based on pay period start date
            YEAR(pp.start_date) = p_year AND MONTH(pp.start_date) = p_month
    )
    -- Select all individual employee rows for the report
    SELECT
		CONCAT(p_month, "-" ,p_year) AS `MM-YY`,
        CAST(employee_id AS CHAR) AS `Employee No`,
        full_name AS `Employee Full Name`,
        position_title AS `Position`,
        department_name AS `Department`,
        CONCAT('₱', FORMAT(gross_income, 2)) AS `Gross Income`,
        sss_number AS `Social Security No.`,
        CONCAT('₱', FORMAT(sss_contribution, 2)) AS `Social Security Contribution`,
        philhealth_number AS `Philhealth No.`,
        CONCAT('₱', FORMAT(philhealth_contribution, 2)) AS `Philhealth Contribution`,
        pagibig_number AS `Pag-ibig No.`,
        CONCAT('₱', FORMAT(pagibig_contribution, 2)) AS `Pag-Ibig Contribution`,
        tin_number AS `TIN`,
        CONCAT('₱', FORMAT(withholding_tax, 2)) AS `Withholding Tax`,
        CONCAT('₱', FORMAT(net_income, 2)) AS `Net Pay`
    FROM
        PayslipDetails

    UNION ALL

    -- Add the total row for all aggregated values
    SELECT
		'TOTAL' AS `MM-YY`,
        '' AS `Employee No`,
        '' AS `Employee Full Name`,
        '' AS `Position`,
        '' AS `Department`,
        CONCAT('₱', FORMAT(SUM(gross_income), 2)) AS `Gross Income`,
        '' AS `Social Security No.`,
        CONCAT('₱', FORMAT(SUM(sss_contribution), 2)) AS `Social Security Contribution`,
        '' AS `Philhealth No.`,
        CONCAT('₱', FORMAT(SUM(philhealth_contribution), 2)) AS `Philhealth Contribution`,
        '' AS `Pag-ibig No.`,
        CONCAT('₱', FORMAT(SUM(pagibig_contribution), 2)) AS `Pag-Ibig Contribution`,
        '' AS `TIN`,
        CONCAT('₱', FORMAT(SUM(withholding_tax), 2)) AS `Withholding Tax`,
        CONCAT('₱', FORMAT(SUM(net_income), 2)) AS `Net Pay`
    FROM
        PayslipDetails;

END ;;
DELIMITER ;
