        py.days_worked AS "Distinct Days Worked", -- Could have worked less than 8 hours; Counts only DISTINCT days worked
        py.total_hours_worked AS "Hours Worked", -- Regular Hours
        py.total_overtime_hours AS "Overtime Hours", -- Hours that exceeded 8
        
        py.gross_income AS "Gross Income", -- Gross Income = (Hours Worked * Hourly Rate) + (Overtime Hours * Hourly Rate * Overtime Rate Multiplier)
        
        
        -- BENEFITS
