CREATE DEFINER=`root`@`localhost` PROCEDURE `RejectLeave`(
    IN v_leave_record_id INT,
    IN v_rejected_by INT,
    IN v_rejection_reason TEXT
)
BEGIN
    -- Variables
    DECLARE v_current_status ENUM('PENDING','APPROVED','REJECTED');
    DECLARE v_affected_rows INT DEFAULT 0;
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Get current status
    SELECT status 
    INTO v_current_status
    FROM leave_record 
    WHERE leave_record_id = v_leave_record_id;
    
    -- Check if leave record exists
    IF v_current_status IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Leave record not found';
    END IF;
    
    -- Check if leave is already processed
    IF v_current_status != 'PENDING' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Leave record is already processed';
    END IF;
    
    -- Reject the leave
    UPDATE leave_record
    SET 
        status = 'REJECTED',
        remarks = v_rejection_reason,
        status_updated_by = v_rejected_by,
        status_updated_at = NOW()
    WHERE leave_record_id = v_leave_record_id;
    
    -- Check if update was successful
    SET v_affected_rows = ROW_COUNT();
    
    IF v_affected_rows = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Failed to reject leave record';
    END IF;
    
    -- Return updated record
    SELECT 
        lr.leave_record_id,
        lr.employee_id,
        lr.leave_type_id,
        lt.name AS leave_type_name,
        lr.application_date,
        lr.applied_start_date,
        lr.applied_end_date,
        lr.days_used,
        lr.reason,
        lr.status,
        lr.status_updated_by,
        lr.status_updated_at,
        lr.remarks
    FROM leave_record lr
    INNER JOIN leave_type lt ON lr.leave_type_id = lt.leave_type_id
    WHERE lr.leave_record_id = v_leave_record_id;
    
    -- Commit transaction
    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
