CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateEmployeeAddress`(
    -- Input parameters for the employee's address details
    IN emp_id INT,
    IN building_street VARCHAR(255),
    IN barangay VARCHAR(100),
    IN city_municipality VARCHAR(100),
    IN province VARCHAR(100),
    IN zipcode VARCHAR(10),

    -- EmployeeAddress Table variable
    IN address_type ENUM('HOME','EMERGENCY')
)
BEGIN
    -- Declare variable to hold the existing address ID for the employee and address type
    DECLARE existing_address_id INT;

    -- Standard error handler to rollback on any SQL exception
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL; -- Re-raise the original exception
    END;

    -- Start a transaction to ensure atomicity of operations
    START TRANSACTION;

    -- 1. Get the current address ID for this employee and address type
    SELECT ea.address_id
    INTO existing_address_id
    FROM employee_address ea
    WHERE ea.employee_id = emp_id AND ea.address_type = address_type;

    -- 2. Update the existing address record directly.
    UPDATE address
    SET
        building_street = building_street,
        barangay = barangay,
        city_municipality = city_municipality,
        province = province,
        zipcode = zipcode
    WHERE address_id = existing_address_id;

    -- Commit the transaction if all operations were successful
    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
