CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateEmployeeRecord`(
    -- Employee identification
    IN p_employee_id INT,
    
    -- Employee Table variables (NULL means no change)
    IN p_new_first_name VARCHAR(50),
    IN p_new_last_name VARCHAR(50),
    IN p_new_gender ENUM('MALE','FEMALE'),
    IN p_new_birthday DATE,
    IN p_new_phone_number VARCHAR(15),
    IN p_new_sss_number VARCHAR(15),
    IN p_new_philhealth_number VARCHAR(15),
    IN p_new_tin_number VARCHAR(15),
    IN p_new_pagibig_number VARCHAR(15),
    IN p_new_employment_status ENUM('REGULAR','PROBATIONARY'),
    IN p_new_department ENUM('HUMAN_RESOURCES','INFORMATION_TECHNOLOGY','FINANCE','SALES_AND_MARKETING','SUPPLY_CHAIN_AND_LOGISTICS','CUSTOMER_SERVICE','OPERATIONS'),
    IN p_new_supervisor_id INT,
    
    -- PositionSalaryHistory Table variables (NULL means no change)
    IN p_new_job_title VARCHAR(255),       -- Changed from position_id to job_title
    IN p_new_job_description TEXT,         -- Optional job description
    IN p_new_basic_salary DECIMAL(10,2),
    IN p_new_rice_subsidy DECIMAL(10,2),
    IN p_new_phone_allowance DECIMAL(10,2),
    IN p_new_clothing_allowance DECIMAL(10,2),
    
    -- Address Table variables (NULL means no change)
    IN p_new_building_street VARCHAR(255),
    IN p_new_barangay VARCHAR(100),
    IN p_new_city_municipality VARCHAR(100),
    IN p_new_province VARCHAR(100),
    IN p_new_zipcode VARCHAR(10),
    IN p_address_type ENUM('HOME','EMERGENCY') -- Which address to update
    
)
BEGIN
    -- Variables to store original values
    DECLARE v_original_first_name VARCHAR(50);
    DECLARE v_original_last_name VARCHAR(50);
    DECLARE v_original_gender ENUM('MALE','FEMALE');
    DECLARE v_original_birthday DATE;
    DECLARE v_original_phone_number VARCHAR(15);
    DECLARE v_original_sss_number VARCHAR(15);
    DECLARE v_original_philhealth_number VARCHAR(15);
    DECLARE v_original_tin_number VARCHAR(15);
    DECLARE v_original_pagibig_number VARCHAR(15);
    DECLARE v_original_employment_status ENUM('REGULAR','PROBATIONARY');
    DECLARE v_original_department ENUM('HUMAN_RESOURCES','INFORMATION_TECHNOLOGY','FINANCE','SALES_AND_MARKETING','SUPPLY_CHAIN_AND_LOGISTICS','CUSTOMER_SERVICE','OPERATIONS');
    DECLARE v_original_supervisor_id INT;
    
    -- Error handling
    DECLARE exit handler for sqlexception
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Step 1: Fetch original employee values
    SELECT first_name, last_name, gender, birthday, phone_number, 
           sss_number, philhealth_number, tin_number, pagibig_number,
           employment_status, department, supervisor_id
    INTO v_original_first_name, v_original_last_name, v_original_gender, 
         v_original_birthday, v_original_phone_number, v_original_sss_number,
         v_original_philhealth_number, v_original_tin_number, v_original_pagibig_number,
         v_original_employment_status, v_original_department, v_original_supervisor_id
    FROM employee
    WHERE employee_id = p_employee_id;
    
    -- Step 2: Update position/salary if provided
    IF p_new_job_title IS NOT NULL OR p_new_basic_salary IS NOT NULL OR 
       p_new_rice_subsidy IS NOT NULL OR p_new_phone_allowance IS NOT NULL OR 
       p_new_clothing_allowance IS NOT NULL THEN
        
        -- Call the UpdatePositionSalaryOfEmployee procedure
        CALL UpdatePositionSalaryOfEmployee(
            p_employee_id,
            p_new_job_title,
            p_new_job_description,
            p_new_basic_salary,
            p_new_rice_subsidy,
            p_new_phone_allowance,
            p_new_clothing_allowance
        );
    END IF;
    
    -- Step 3: Update employee table
    UPDATE employee
    SET 
        first_name = CASE 
            WHEN p_new_first_name IS NOT NULL AND p_new_first_name <> v_original_first_name 
            THEN p_new_first_name 
            ELSE first_name 
        END,
        last_name = CASE 
            WHEN p_new_last_name IS NOT NULL AND p_new_last_name <> v_original_last_name 
            THEN p_new_last_name 
            ELSE last_name 
        END,
        gender = CASE 
            WHEN p_new_gender IS NOT NULL AND p_new_gender <> v_original_gender 
            THEN p_new_gender 
            ELSE gender 
        END,
        birthday = CASE 
            WHEN p_new_birthday IS NOT NULL AND p_new_birthday <> v_original_birthday 
            THEN p_new_birthday 
            ELSE birthday 
        END,
        phone_number = CASE 
            WHEN p_new_phone_number IS NOT NULL AND p_new_phone_number <> v_original_phone_number 
            THEN p_new_phone_number 
            ELSE phone_number 
        END,
        sss_number = CASE 
            WHEN p_new_sss_number IS NOT NULL AND p_new_sss_number <> v_original_sss_number 
            THEN p_new_sss_number 
            ELSE sss_number 
        END,
        philhealth_number = CASE 
            WHEN p_new_philhealth_number IS NOT NULL AND p_new_philhealth_number <> v_original_philhealth_number 
            THEN p_new_philhealth_number 
            ELSE philhealth_number 
        END,
        tin_number = CASE 
            WHEN p_new_tin_number IS NOT NULL AND p_new_tin_number <> v_original_tin_number 
            THEN p_new_tin_number 
            ELSE tin_number 
        END,
        pagibig_number = CASE 
            WHEN p_new_pagibig_number IS NOT NULL AND p_new_pagibig_number <> v_original_pagibig_number 
            THEN p_new_pagibig_number 
            ELSE pagibig_number 
        END,
        employment_status = CASE 
            WHEN p_new_employment_status IS NOT NULL AND p_new_employment_status <> v_original_employment_status 
            THEN p_new_employment_status 
            ELSE employment_status 
        END,
        department = CASE 
            WHEN p_new_department IS NOT NULL AND p_new_department <> v_original_department 
            THEN p_new_department 
            ELSE department 
        END,
        supervisor_id = CASE 
            WHEN p_new_supervisor_id IS NOT NULL AND p_new_supervisor_id <> v_original_supervisor_id 
            THEN p_new_supervisor_id 
            ELSE supervisor_id 
        END
    WHERE employee_id = p_employee_id;
    
    -- Step 4: Update address if provided using the dedicated procedure
    IF p_new_building_street IS NOT NULL OR p_new_barangay IS NOT NULL OR 
       p_new_city_municipality IS NOT NULL OR p_new_province IS NOT NULL OR 
       p_new_zipcode IS NOT NULL THEN
        
        -- Call the UpdateEmployeeAddress procedure
        CALL UpdateEmployeeAddress(
            p_employee_id,
            p_new_building_street,
            p_new_barangay,
            p_new_city_municipality,
            p_new_province,
            p_new_zipcode,
            p_address_type
        );
    END IF;
    
    -- Commit transaction if all steps succeed
    COMMIT;
    
END ;;
DELIMITER ;
