CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdatePositionSalaryOfEmployee`(
    -- Input parameters for employee and their new/updated position and salary details
    IN emp_id INT,
    IN job_title VARCHAR(255),
    IN job_description TEXT, -- Optional job description for new positions
    IN basic_salary DECIMAL(10,2),
    IN rice_subsidy DECIMAL(10,2),
    IN phone_allowance DECIMAL(10,2),
    IN clothing_allowance DECIMAL(10,2)
)
BEGIN
    -- Declare variables to hold current employee's position and salary details
    DECLARE v_current_position_salary_history_id INT;
    DECLARE v_current_position_id INT;
    DECLARE v_current_job_title VARCHAR(255);
    DECLARE v_current_basic_salary DECIMAL(10,2);
    DECLARE v_current_rice_subsidy DECIMAL(10,2);
    DECLARE v_current_phone_allowance DECIMAL(10,2);
    DECLARE v_current_clothing_allowance DECIMAL(10,2);

    -- Declare variable for the new or existing position ID
    DECLARE v_effective_position_id INT;

    -- Declare variable to check if an active record for today already exists
    DECLARE v_today_active_psh_id INT DEFAULT NULL;

    -- Standard error handler to rollback on any SQL exception
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL; -- Re-raise the original exception
    END;

    -- Start a transaction to ensure atomicity of operations
    START TRANSACTION;

    -- 1. Retrieve the current active position and salary details for the employee
    SELECT
        psh.position_salary_history_id,
        psh.position_id,
        jp.title,
        psh.basic_salary,
        psh.rice_subsidy,
        psh.phone_allowance,
        psh.clothing_allowance
    INTO
        v_current_position_salary_history_id,
        v_current_position_id,
        v_current_job_title,
        v_current_basic_salary,
        v_current_phone_allowance,
        v_current_rice_subsidy,
        v_current_clothing_allowance
    FROM
        position_salary_history psh
    INNER JOIN
        employee e ON e.position_salary_history_id = psh.position_salary_history_id
    INNER JOIN
        job_position jp ON psh.position_id = jp.position_id
    WHERE
        e.employee_id = emp_id
        AND psh.effective_end_date IS NULL; -- Ensure we get the currently active record

    -- 2. Determine the position_id: Use existing or create new if job_title changed
    IF job_title IS NOT NULL AND UPPER(TRIM(job_title)) <> UPPER(TRIM(v_current_job_title)) THEN
        SELECT position_id INTO v_effective_position_id
        FROM job_position
        WHERE UPPER(TRIM(title)) = UPPER(TRIM(job_title))
        LIMIT 1;

        IF v_effective_position_id IS NULL THEN
            INSERT INTO job_position (title, description)
            VALUES (TRIM(job_title), job_description);
            SET v_effective_position_id = LAST_INSERT_ID();
        END IF;
    ELSE
        SET v_effective_position_id = v_current_position_id;
    END IF;

    -- 3. Check if any relevant changes (position or salary components) have occurred
    IF (v_effective_position_id <> v_current_position_id) OR
       (basic_salary IS NOT NULL AND basic_salary <> v_current_basic_salary) OR
       (rice_subsidy IS NOT NULL AND rice_subsidy <> v_current_rice_subsidy) OR
       (phone_allowance IS NOT NULL AND phone_allowance <> v_current_phone_allowance) OR
       (clothing_allowance IS NOT NULL AND clothing_allowance <> v_current_clothing_allowance)
    THEN
        -- Check if there's already an active record for today
        SELECT position_salary_history_id
        INTO v_today_active_psh_id
        FROM position_salary_history
        WHERE employee_id = emp_id
          AND effective_start_date = CURDATE()
          AND effective_end_date IS NULL;

        IF v_today_active_psh_id IS NOT NULL THEN
            -- If an active record for today exists, update it
            UPDATE position_salary_history
            SET
                position_id = v_effective_position_id,
                basic_salary = COALESCE(basic_salary, v_current_basic_salary),
                rice_subsidy = COALESCE(rice_subsidy, v_current_rice_subsidy),
                phone_allowance = COALESCE(phone_allowance, v_current_phone_allowance),
                clothing_allowance = COALESCE(clothing_allowance, v_current_clothing_allowance)
            WHERE position_salary_history_id = v_today_active_psh_id;

            -- Ensure the employee record points to this updated record (it should already)
            UPDATE employee
            SET position_salary_history_id = v_today_active_psh_id
            WHERE employee_id = emp_id;

        ELSE
            -- If no active record for today exists, proceed with closing previous and inserting new

            -- 4. Close current active record for the specific employee (set end date to yesterday)
            UPDATE position_salary_history
            SET effective_end_date = CURDATE() - INTERVAL 1 DAY
            WHERE employee_id = emp_id AND effective_end_date IS NULL;

            -- 5. Insert new PositionSalaryHistory record
            INSERT INTO position_salary_history (
                employee_id,
                position_id,
                basic_salary,
                rice_subsidy,
                phone_allowance,
                clothing_allowance,
                effective_start_date,
                effective_end_date
            )
            VALUES (
                emp_id,
                v_effective_position_id,
                COALESCE(basic_salary, v_current_basic_salary),
                COALESCE(rice_subsidy, v_current_rice_subsidy),
                COALESCE(phone_allowance, v_current_phone_allowance),
                COALESCE(clothing_allowance, v_current_clothing_allowance),
                CURDATE(), -- New record starts today
                NULL       -- Currently active
            );

            -- 6. Update the employee record to reference the new position salary history
            UPDATE employee
            SET position_salary_history_id = LAST_INSERT_ID()
            WHERE employee_id = emp_id;
        END IF;
    END IF;

    -- Commit transaction if all steps succeed
    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
