CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateUserCredential`(
    -- Employee identification
    IN v_employee_id INT,
    IN new_password VARCHAR(255),
    IN new_role ENUM('EMPLOYEE','ADMIN','HR','IT','FINANCE') 
)
BEGIN 
    -- Variables for validation
    DECLARE v_affected_rows INT DEFAULT 0;
    
    -- Error handling
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Step 1: Update user credential table
    UPDATE user_credential 
    SET 
        password = new_password,
        user_role = new_role
    WHERE employee_id = v_employee_id;
    
    -- Check if any rows were affected
    SET v_affected_rows = ROW_COUNT();
    
    IF v_affected_rows = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Employee ID not found';
    END IF;
    
    -- Commit transaction if all steps succeed
    COMMIT;
    
END ;;
DELIMITER ;
